22	export class ModelLoader {
23	  private _gltf: GLTFLoader;
24	  private _draco: DRACOLoader | null = null;
25	  private _texture: THREE.TextureLoader;
26	  private _hdr: InstanceType<typeof HDRLoader>;
27	  private _modelMap = new Map<string, THREE.Group>();
28	  private _clipMap = new Map<string, THREE.AnimationClip[]>();
29	
30	  constructor() {
31	    this._gltf = new GLTFLoader();
32	    registerPBRSpecularGlossinessPlugin(this._gltf);
33	    this._setupDRACO();
34	    this._texture = new THREE.TextureLoader();
35	    this._hdr = new HDRLoader();
36	  }
37	
38	  private _setupDRACO(): void {
39	    try {
40	      this._draco = new DRACOLoader();
41	      
42	      this._draco.setDecoderPath(
43	        "https://www.gstatic.com/draco/versioned/decoders/1.5.7/",
44	      );
45	      this._gltf.setDRACOLoader(this._draco);
46	    } catch (error) {
47	      this._draco = null;
48	    }
49	  }
50	
51	  clearModelCache(): void {
52	    this._disposeCachedModels();
53	    this._modelMap.clear();
54	    this._clipMap.clear();
55	  }
56	
57	  dispose(): void {
58	    this._disposeCachedModels();
59	    this._modelMap.clear();
60	    this._clipMap.clear();
61	    this._draco?.dispose();
62	    this._draco = null;
63	  }
64	
65	  private _disposeCachedModels(): void {
66	    this._modelMap.forEach((group) => disposeObject3D(group));
67	  }
68	
69	  loadGLTF(
70	    scene: THREE.Scene | null,
71	    url: string,
72	    options: LoadGLTFOptions = {},
73	  ): Promise<LoadGLTFResult> {
74	    const cached = this._modelMap.get(url);
75	    if (cached) {
76	      const clone = cached.clone(true) as THREE.Group;
77	      this._cloneMaterialsInPlace(clone);
78	      this._applyTransform(clone, options);
79	      const clips = this._clipMap.get(url) ?? [];
80	      const mixers =
81	        clips.length > 0 ? this._createMixersFromClips(clips, clone) : [];
82	      return Promise.resolve({ model: clone, mixers });
83	    }
84	
85	    if (!scene) return Promise.resolve({ model: null, mixers: [] });
86	    return new Promise<LoadGLTFResult>((resolve, reject) => {
87	      this._gltf.load(
88	        url,
89	        (gltf) => {
90	          const model = gltf.scene;
91	          this._applyTransform(model, options);
92	          this._setupModelUserData(model);
93	          this._setupMeshes(model);
94	          this._modelMap.set(url, model);
95	          this._clipMap.set(url, gltf.animations ?? []);
96	          if (options.addToScene !== false) scene.add(model);
97	          const mixers = this._createMixers(gltf, model);
98	          resolve({ model, mixers });
99	        },
100	        undefined,
101	        reject,
102	      );
103	    });
104	  }
105	
106	  async loadTexture(url: string): Promise<THREE.Texture> {
107	    return new Promise<THREE.Texture>((resolve, reject) => {
108	      this._texture.load(url, resolve, undefined, reject);
109	    });
110	  }
111	
112	  async loadHdrTexture(url: string): Promise<THREE.Texture> {
113	    return this._hdr.loadAsync(url);
114	  }
115	
116	  private _applyTransform(model: THREE.Group, options: LoadGLTFOptions): void {
117	    if (options.position) model.position.set(...options.position);
118	    if (options.scale) model.scale.set(...options.scale);
119	    if (options.rotation) model.rotation.set(...options.rotation);
120	  }
121	
122	  private _setupModelUserData(model: THREE.Object3D): void {
123	    model.userData.selectable = true;
124	    model.userData.isModel = true;
125	  }
126	
127	  private _setupMeshes(model: THREE.Object3D): void {
128	    model.traverse((child) => {
129	      if (!(child as THREE.Mesh).isMesh) return;
130	      const mesh = child as THREE.Mesh;
131	      mesh.userData.selectable = true;
132	      mesh.userData.isModel = true;
133	    });
134	  }
135	
136	  private _cloneMaterialsInPlace(root: THREE.Object3D): void {
137	    root.traverse((child) => {
138	      const mesh = child as THREE.Mesh;
139	      if (!mesh.isMesh) return;
140	      const material = mesh.material;
141	      if (Array.isArray(material)) {
142	        mesh.material = material.map((entry) => entry.clone());
143	        return;
144	      }
145	      if (material) {
146	        mesh.material = material.clone();
147	      }
148	    });
149	  }
150	
151	  private _createMixers(
152	    gltf: { animations?: THREE.AnimationClip[] },
153	    model: THREE.Object3D,
154	  ): THREE.AnimationMixer[] {
155	    const mixers: THREE.AnimationMixer[] = [];
156	    if (!gltf.animations?.length) return mixers;
157	    const mixer = new THREE.AnimationMixer(model);
158	    gltf.animations.forEach((anim) => mixer.clipAction(anim).play());
159	    mixers.push(mixer);
160	    return mixers;
161	  }
162	
163	  private _createMixersFromClips(
164	    clips: THREE.AnimationClip[],
165	    model: THREE.Object3D,
166	  ): THREE.AnimationMixer[] {
167	    if (clips.length === 0) return [];
168	    const mixer = new THREE.AnimationMixer(model);
169	    clips.forEach((clip) => mixer.clipAction(clip).play());
170	    return [mixer];
171	  }
172	}
