1	import * as THREE from "three";
2	import { EnvSetup } from "../../app/EnvSetup.js";
3	import { SceneObject } from "../../core/SceneObject.js";
4	import { THREE_LAYER_ROCKET } from "../../core/setup.js";
5	import type {
6	  RocketFlameStateSnapshot,
7	  RocketFlameOptions,
8	  RocketObjectOptions,
9	  RocketPort,
10	  RocketTweenProps,
11	} from "../../types/object.types.js";
12	import { Helpers } from "../../utils/Helpers.js";
13	import { Logger } from "../../utils/Logger.js";
