17	const ROCKET_CLASS = "Rocket";
18	const ROCKET_FLAME_SHADER_KEY = "rocket-flame";
19	const DEFAULT_FLAME_SCALE = { x: 1.65, y: 3.4, z: 1 };
20	const DEFAULT_FLAME_OFFSET = { x: 0, y: -0.35, z: 0 };
21	const DEFAULT_FLAME_ROTATION = { x: 0, y: 0, z: 0 };
22	const DEFAULT_FLAME_OPACITY = 0.9;
23	const DEFAULT_FLAME_RENDER_ORDER = 5;
24	const DEFAULT_FLAME_SPEED = 2;
25	const DEFAULT_FLAME_WAVE = 1.2;
26	const DEFAULT_FLAME_ANCHOR_NAME_INCLUDES = [
27	  "flame",
28	  "nozzle",
29	  "thruster",
30	  "engine",
31	  "exhaust",
32	] as const;
